svg.script:
// 
document.addEventListener('DOMContentLoaded', () => {
  const estacoes = document.querySelectorAll('.estacao-btn');

  estacoes.forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Aqui você pode colocar a lógica do seu projeto (abrir painel, redirecionar, etc.)
      const nomeDaEstacao = e.target.textContent.trim();
      console.log('Estação clicada:', nomeDaEstacao);
      alert('Você selecionou: ' + nomeDaEstacao);
    });
  });
});
//
